function task015_regression_checks()
% Focused invariant checks on dimensions outside the public fixture.

isotopes={'19F','14N'};
shifts={-100,25};
rates=[3.7 8.25];

for c=1:numel(isotopes)
    systems=cell(1,2); equilibria=cell(1,2); observables=zeros(1,2);
    formalisms={'sphten-liouv','zeeman-liouv'};

    for f=1:numel(formalisms)
        [spin_system,H]=make_system(isotopes{c},shifts{c},rates(c),formalisms{f});
        rho_eq=equilibrium(spin_system,H);
        R=relaxation(spin_system);
        unit=unit_state(spin_system);
        probe=state(spin_system,'Lz',1);

        unit_residual=norm(R*unit,2);
        response_rate=-real(probe'*R*probe)/(probe'*probe);
        assert(unit_residual<1e-11);
        assert(abs(response_rate-rates(c))<1e-11);

        Rt_ime=thermalize(spin_system,R,[],[],rho_eq,'IME');
        Rt_scaled=thermalize(spin_system,R,[],[],7*rho_eq,'IME');
        Rt_dibari=thermalize(spin_system,R,H,...
                            spin_system.rlx.temperature,[],'dibari');
        assert(norm(Rt_ime-Rt_scaled,2)<1e-11);
        assert(norm(Rt_ime*rho_eq,2)<1e-9);
        assert(norm(Rt_dibari*rho_eq,2)<1e-9);
        assert(norm(step(spin_system,1i*Rt_ime,rho_eq,0.02)-rho_eq,2)<1e-9);
        assert(norm(step(spin_system,1i*Rt_dibari,rho_eq,0.02)-rho_eq,2)<1e-9);

        if strcmp(formalisms{f},'sphten-liouv')
            population=unit'*rho_eq;
        else
            d=prod(spin_system.comp.mults);
            identity=speye(d); identity=identity(:);
            population=identity'*rho_eq;
        end
        assert(abs(population-1)<1e-11);

        systems{f}=spin_system;
        equilibria{f}=rho_eq;
        observables(f)=trace(probe'*rho_eq);
    end

    % Compare represented density matrices and physical observables, rather
    % than raw generators (the spherical space may be symmetry-reduced).
    P=sphten2zeeman(systems{1});
    d=prod(systems{1}.comp.mults);
    equilibrium_residual=norm(equilibria{2}-P*equilibria{1}/sqrt(d),2);
    observable_residual=abs(observables(1)-observables(2));
    fprintf('REGRESSION_DIAG|%s|observable=%g|equilibrium=%g\n',...
            isotopes{c},observable_residual,equilibrium_residual);
    assert(observable_residual<1e-11);
    assert(equilibrium_residual<1e-11);

    fprintf('REGRESSION_OK|%s|hilbert_dim=%d|rate=%g\n',...
            isotopes{c},d,rates(c));
end
end

function [spin_system,H]=make_system(isotope,shift,rate,formalism)
sys.magnet=9.4;
sys.isotopes={isotope};
sys.output='hush';
sys.disable={'hygiene','pt','zte','dss','trajlevel','merge'};
sys.enable={};

inter.zeeman.scalar={shift};
inter.coupling.scalar=cell(1,1);
inter.relaxation={'damp'};
inter.equilibrium='zero';
inter.temperature=12;
inter.damp_rate=rate;
inter.rlx_keep='diagonal';

bas.formalism=formalism;
bas.approximation='none';

spin_system=create(sys,inter);
spin_system=basis(spin_system,bas);
omega=trace(spin_system.inter.zeeman.matrix{1})/3;
H=omega*operator(spin_system,'Lz',1,'left');
end
